INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷规定百官上元节放假十日", "description": "朝廷给百官上元节十天假，并把这一办法定为规例。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "308f17c2-9992-5f73-97c6-cbae732b126f"}, {"title": "明廷在南郊祭祀天地", "description": "朝廷在南郊举行祭祀天地的大礼。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年正月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9a5b9213-f291-5ad7-a970-83e66a57a4a9"}, {"title": "明廷在巡行所经郡县慰问老人", "description": "朝廷派使者慰问皇帝巡行所经郡县的老人，赐八十岁以上者酒肉，九十岁以上者另给帛。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2dc597bc-2ea9-5aff-8e8f-fb521aee1e22"}, {"title": "明廷召刘彦才等九十二名退休官员署职", "description": "朝廷征召已经退休的知府刘彦才等九十二人，分别代理府、州、县的职务。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dd96c7cc-a7b5-58da-98ce-113184cac0e9"}, {"title": "朱棣北巡前告祭天地宗庙社稷", "description": "朱棣决定北巡，朝廷为此告祭天地、宗庙和社稷。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "81ff853e-4b3e-5b35-8244-47144ec80057"}, {"title": "朱棣离京北巡，朱高炽监国", "description": "朱棣从京师启程北巡，皇太子朱高炽监国。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fdece14-46af-5470-a211-17d2496cb07b"}, {"title": "张辅王友率军出讨简定", "description": "张辅、王友率军征讨交阯的简定。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fa65e781-0e4c-52b1-ba95-49c937196ce2"}, {"title": "朱棣拜谒凤阳皇陵", "description": "朱棣于二月戊子拜谒凤阳皇陵。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年二月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "50002ae6-2671-5ecd-9a76-9a17e5a86eba"}, {"title": "朱棣行至东平州，望祭泰山", "description": "朱棣巡行驻于东平州，遥祭泰山。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "877d173d-e7b9-56ec-a678-df93aa2118ac"}, {"title": "朱棣行至景州，望祭恒山", "description": "朱棣巡行驻于景州，遥祭恒山。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "942e5745-04b5-5032-9e3a-81de5efe2c74"}, {"title": "平安自杀身亡", "description": "本纪记载，平安于三月乙卯自杀身亡。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "61c11651-c345-5d80-bf43-83e965d383d8"}, {"title": "朱棣到达北京", "description": "朱棣北巡抵达北京。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c8300142-67a6-576c-99ff-9a3e7f4954a2"}, {"title": "明廷在北京赏赐官吏军民", "description": "朱棣到北京后，朝廷在癸亥大加赏赐官吏和军民。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "80702952-0dfb-5d72-8d4d-3e0f6faff00c"}, {"title": "明廷赦免部分靖难将士和北京效力者", "description": "朝廷下诏，先前起兵时的将士及曾在北京效力的百姓，犯杂犯死罪者免罪。已经充军的官员恢复职务，军民各归原籍伍。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a7a82e74-4857-5599-914a-7a67256a0564"}, {"title": "柳升在青州海上击败倭寇", "description": "柳升在青州海上击败倭寇，朝廷下敕命其回师。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年三月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fb44e536-2d55-5df0-a490-797b2c4d3525"}, {"title": "朱高炽代行太庙祭祀", "description": "四月初一，皇太子朱高炽代理主持太庙祭祀。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年四月癸酉朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11afed3a-f96e-5c40-8717-0d56916a5a5c"}, {"title": "李珪派将击退进犯钦州的海寇", "description": "海上武装进犯钦州，副总兵李珪派部将将其击败。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年四月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e1e905b7-d6d8-5a10-894d-fa2eed513d4a"}, {"title": "明廷令六科按月汇报皇太子所决事务", "description": "朝廷命六科每月汇总一次皇太子已裁决的政务，上奏皇帝。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年闰四月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2fdf1e13-50e5-5a61-a1e0-76ea2d1bccd2"}, {"title": "朱棣令行在司法官署重案复奏五次", "description": "朱棣告谕随驾的司法官署，重罪案件须复奏五次。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年闰四月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b4a1df70-baae-59a3-9d44-f80638c00082"}, {"title": "明廷在昌平营建山陵并赐山名天寿", "description": "朝廷在昌平营建山陵，将陵山命名为天寿。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年五月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d67dd9c-f8f7-5097-8e11-07573a986025"}, {"title": "明廷封瓦剌马哈木等三人为王", "description": "朝廷册封瓦剌马哈木为顺宁王、太平为贤义王、把秃孛罗为安乐王。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年五月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "04690bee-d1e2-5978-b3ef-7729e644156a"}, {"title": "明廷考察北巡所经官员并奖惩", "description": "朝廷考察北巡所经郡县长官，将政绩列第一的汶上知县史诚祖拔擢，把易州同知张腾关入监狱。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年六月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "20859bda-652c-5c3e-8c41-6ec2e82a94d7"}, {"title": "郭骥出使本雅失里被杀", "description": "给事中郭骥出使本雅失里处，被对方杀害。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年六月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b1e9299-efa4-540b-8ec9-45d005d84e9a"}, {"title": "明廷罢免洪秉等御史并定选任规定", "description": "朝廷斥退御史洪秉等四人，下诏从今不以吏员担任御史。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8862fc5a-067f-5d6d-b5ae-5b2fbf06ccf5"}, {"title": "丘福等奉命率军讨本雅失里", "description": "朝廷以淇国公丘福为征虏大将军，王聪和火真为副将，王忠和李远为左右参将，率军征讨本雅失里。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年七月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19ab3bc9-1e51-5e9a-84b9-50b83668a850"}, {"title": "丘福在胪朐河战败并阵亡", "description": "丘福率军在胪朐河作战失利。丘福、王聪、火真、王忠和李远均在战事中阵亡。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年八月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10620f32-621a-5e23-a0e1-8c6008f24002"}, {"title": "张辅在咸子关击败对手", "description": "本纪记张辅率军在咸子关击败对手。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0043d6d0-61c3-5882-bca9-c79d59c62c54"}, {"title": "本纪记九月初一日食", "description": "本纪记载，九月初一出现日食。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年九月庚午朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d10445d3-5e1c-5b37-a7ab-64bd44df9949"}, {"title": "张辅在太平海口取胜", "description": "本纪记张辅率军在太平海口击败对手。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec034dbd-3109-5a04-8ee0-fbb02140cebb"}, {"title": "明廷追赠李远王聪，朱棣决定亲征", "description": "朝廷追赠北征阵亡的李远为莒国公、王聪为漳国公。朱棣随后决定亲征。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年九月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b01ebeaa-501c-5ce6-8cbd-252849b8401e"}, {"title": "郑亨率军巡视边地", "description": "武安侯郑亨率领军队巡视边地。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年九月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1989cde1-e217-580e-a3f8-883a504bd490"}, {"title": "郭亮在开平部署守备", "description": "成安侯郭亮在开平部署守备。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年九月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4236b30b-3dd2-5f76-9e1f-c4174cc23362"}, {"title": "明廷削去丘福封爵并迁其家属至海南", "description": "朝廷削去丘福的封爵，将他的家属迁往海南。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年十月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc44e82b-9f17-5d2c-bfca-0ec94afe9fcb"}, {"title": "张辅在美良擒获简定", "description": "张辅在美良擒获简定，将他送往京师。本纪记简定随后被处死。", "start_year": 1409, "end_year": 1409, "time_original": "永乐七年十一月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d4b4a2d3-27e6-5f1a-9bea-032b78170481"}, {"title": "明廷减免济宁至良乡沿线长期转运民户的田租", "description": "朝廷对济宁至良乡沿线连续多年承担接力运输的民户，免征一年田租。", "start_year": 1410, "end_year": 1410, "time_original": "永乐七年十二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "079bf7d9-e8f0-56fe-a1d6-97b10d9c57cb"}, {"title": "明廷召回张辅", "description": "朝廷于十二月乙丑召张辅返回。", "start_year": 1410, "end_year": 1410, "time_original": "永乐七年十二月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "091b840a-06ea-5f72-8d4a-07fb27e61c23"}, {"title": "满剌加等地遣使来贡", "description": "本纪记载，满剌加、哈烈、撒马儿罕、火州、古里、占城、苏门答剌及琉球中山、山南来贡，暹罗和榜葛剌来贡两次。 按原历纪年，事情发生在公元1409至1410年之间。", "start_year": null, "end_year": null, "time_original": "永乐七年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32bf2287-c3c7-5409-9adf-13a1c7c68e49"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

